 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0 = min(y for y, x in cells)
            c0 = min(x for y, x in cells)
            shape = [(y-r0, x-c0) for y, x in cells]
            bh = max(y for y, x in shape) + 1
            bw = max(x for y, x in shape) + 1
            objects.append((c0, r0, color, shape, bh, bw))

    objects.sort(key=lambda obj: (obj[0], obj[1]))
    out = [[0] * w for _ in range(h)]
    top = left = 0
    for i, (_, _, color, shape, bh, bw) in enumerate(objects):
        if i:
            prev = objects[i - 1]
            top += prev[4] - 1
            left += prev[5] - 1
        for dy, dx in shape:
            y, x = top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


